package com.lindum.mlkit.vision.posedetector.classificationimport android.content.Contextimport android.os.Looperimport android.util.Logimport androidx.annotation.WorkerThreadimport com.google.common.base.Preconditionsimport com.google.gson.Gsonimport com.google.mlkit.vision.pose.Poseimport com.lindum.mlkit.vision.CameraXLivePreviewActivityimport com.lindum.mlkit.vision.CameraXLivePreviewActivity.Companion.addWarnPartimport com.lindum.mlkit.vision.CameraXLivePreviewActivity.Companion.poseEntityListimport com.lindum.mlkit.vision.posedetector.PoseAngleDetectorimport com.lindum.mlkit.vision.posedetector.PosePartimport com.orhanobut.logger.Loggerimport java.io.BufferedReaderimport java.io.IOExceptionimport java.io.InputStreamReaderimport java.util.Locale/** * Accepts a stream of [Pose] for classification and Rep counting. */class PoseClassifierProcessor @WorkerThread constructor(    context: Context,    isStreamMode: Boolean) {    private val poseClassifyFileName = arrayOf<String>(        "lsttlsj"    )    private val isStreamMode: Boolean    private var emaSmoothing: EMASmoothing? = null    private var repCounters: MutableList<RepetitionCounter>? = null    private var poseClassifier: PoseClassifier? = null    private var lastRepResult: String? = null    // 置信度    private var con = ""    @Volatile    private var addWarnPartFlag = true    var context: Context    init {        Preconditions.checkState(Looper.myLooper() != Looper.getMainLooper())        this.isStreamMode = isStreamMode        if (isStreamMode) {            emaSmoothing = EMASmoothing()            repCounters = ArrayList<RepetitionCounter>()            lastRepResult = ""        }        this.context = context        loadPoseSamples(context)    }    // TODO: 2022/3/8    private fun loadPoseSamples(context: Context) {        val poseSamples: MutableList<PoseSample?> = ArrayList<PoseSample?>()        try {            if (poseClassifyFileName[CameraXLivePreviewActivity.nowPoseIndex] != "") {//                POSE_SAMPLES_FILE =//                    "pose/" + poseClassifyFileName[CameraXLivePreviewActivity.nowPoseIndex] + ".csv"                POSE_SAMPLES_FILE =                    "pose/lsttlsj.csv"            }            val reader = BufferedReader(                InputStreamReader(context.getAssets().open(POSE_SAMPLES_FILE))            )            var csvLine = reader.readLine()            while (csvLine != null) {                // If line is not a valid {@link PoseSample}, we'll get null and skip adding to the list.                val poseSample = PoseSample.getPoseSample(csvLine, ",")                if (poseSample != null) {                    poseSamples.add(poseSample)                }                csvLine = reader.readLine()            }        } catch (e: IOException) {            Log.e(TAG, "Error when loading pose samples.\n" + e)        }        poseClassifier = PoseClassifier(poseSamples)        if (isStreamMode) {            for (className in POSE_CLASSES) {                repCounters!!.add(RepetitionCounter(className))            }        }    }    /**     * Given a new [Pose] input, returns a list of formatted [String]s with Pose     * classification results.     *     *     * Currently it returns up to 2 strings as following:     * 0: PoseClass : X reps     * 1: PoseClass : [0.0-1.0] confidence     */    @WorkerThread    fun getPoseResult(pose: Pose): MutableList<String?> {        if (POSE_SAMPLES_FILE != "pose/" + poseClassifyFileName[CameraXLivePreviewActivity.nowPoseIndex] + ".csv" && poseClassifyFileName[CameraXLivePreviewActivity.nowPoseIndex] != "") {            loadPoseSamples(context)        }        poseTips = ""        Preconditions.checkState(Looper.myLooper() != Looper.getMainLooper())        val result: MutableList<String?> = ArrayList<String?>()        var classification = poseClassifier!!.classify(pose)        // Update {@link RepetitionCounter}s if {@code isStreamMode}.        if (isStreamMode) {            // Feed pose to smoothing even if no pose found.            classification = emaSmoothing!!.getSmoothedResult(classification)            // Return early without updating repCounter if no pose found.            if (pose.allPoseLandmarks.isEmpty()) {                result.add(lastRepResult)                return result            }            for (repCounter in repCounters!!) {                val repsBefore = repCounter.numRepeats                val repsAfter = repCounter.addClassificationResult(classification)                Log.i("test_count", "${this}--before:$repsBefore")                Log.i("test_count", "${this}--after:$repsAfter")                if (repsAfter > repsBefore) {                    // Play a fun beep when rep counter updates.//                    ToneGenerator tg = new ToneGenerator(AudioManager.STREAM_NOTIFICATION, 100);//                    tg.startTone(ToneGenerator.TONE_PROP_BEEP);                    lastRepResult = String.format(                        Locale.US, "已做 %d 个", repsAfter                    )                    CameraXLivePreviewActivity.countTimes = repsAfter                    Log.i("test_count", "${this}--$repsAfter")                    break                }            }            result.add(lastRepResult)        }        // Add maxConfidence class of current frame to result if pose is found.        checkNotNull(pose)        if (!pose.getAllPoseLandmarks().isEmpty()) {            maxConfidenceClass = classification.getMaxConfidenceClass()            val maxConfidenceClassResult = String.format(                Locale.US,                "%s : %.2f confidence",                maxConfidenceClass,                classification.getClassConfidence(maxConfidenceClass)                        / poseClassifier!!.confidenceRange()            )            confidence =                classification.getClassConfidence(maxConfidenceClass) / poseClassifier!!.confidenceRange()            //            Logger.e("置信度" + confidence);            CameraXLivePreviewActivity.confidence = confidence            if (poseClassifyFileName[CameraXLivePreviewActivity.nowPoseIndex] != "") {                result.add(maxConfidenceClassResult)            }            result.add(" ")            result.add(" ")            result.add(" ")            result.add(" ")            result.add(" ")        }        // 人体关键的监测        val poseAngleDetector = PoseAngleDetector(pose)        // 二维和三维同时显示        val angleText1 =            "左膝3D" + poseAngleDetector.getLeftKnee3DAngle() + "°" + "2D" + poseAngleDetector.getLeftKneeAngle() + "°"        val angleText2 =            "右膝3D" + poseAngleDetector.getRightKnee3DAngle() + "°" + "2D" + poseAngleDetector.getRightKneeAngle() + "°"        val angleText3 =            "左胳3D" + poseAngleDetector.getLeftArm3DAngle() + "°" + "2D" + poseAngleDetector.getLeftArmAngle() + "°"        val angleText4 =            "右胳3D" + poseAngleDetector.getRightArm3DAngle() + "°" + "2D" + poseAngleDetector.getRightArmAngle() + "°"        val angleText5 =            "左躯3D" + poseAngleDetector.getLeftTrunk3DAngle() + "°" + "2D" + poseAngleDetector.getLeftTrunkAngle() + "°"        val angleText6 =            "右躯3D" + poseAngleDetector.getRightTrunk3DAngle() + "°" + "2D" + poseAngleDetector.getRightTrunkAngle() + "°"        val angleText7 =            "左肩3D" + poseAngleDetector.getLeftShoulder3DAngle() + "°" + "2D" + poseAngleDetector.getLeftShoulderAngle() + "°"        val angleText8 =            "右肩3D" + poseAngleDetector.getRightShoulder3DAngle() + "°" + "2D" + poseAngleDetector.getRightShoulderAngle() + "°"        //        result.add(angleText1);//        result.add(angleText2);//        result.add(angleText3);//        result.add(angleText4);//        result.add(angleText5);//        result.add(angleText6);//        result.add(angleText7);//        result.add(angleText8);//        result.add("\n");//        result.add("\n");//        result.add("\n");//        result.add("\n");//        result.add("\n");//        result.add("\n");        con += confidence.toString() + " "        Logger.e(con)        /*              !!!!!!!! 这个类可以理解每次截取一张图片进行判断 ！！！！！！！              !!!!!!!! 这个类可以理解每次截取一张图片进行判断 ！！！！！！！              !!!!!!!! 这个类可以理解每次截取一张图片进行判断 ！！！！！！！             *///                Log.e("TEST", CameraXLivePreviewActivity.countdownSeconds + "S");        // 倒计时结束，开始训练        if (CameraXLivePreviewActivity.countdownSeconds == -1) {            // 动作模式： 普通模式 1 严格模式 2            // 普通模式 待定 todo            // 如果严格模式，则要求每个部位都要精准才算一个有效动作            val mode = 2            // 获取监测的动作实体            val poseEntity = poseEntityList!!.get(CameraXLivePreviewActivity.nowPoseIndex)            // 获取监测部位列表            val monitoringList = poseEntity.getMonitoringPosePartList()            // 固定部位列表            val fixedPartList: MutableList<PosePart> = ArrayList<PosePart>()            // 动态部位列表            val dynamicPart: MutableList<PosePart> = ArrayList<PosePart>()            // 将固定部位和动态部位分别筛选出来            for (part in monitoringList) {                if (part.getPoseType() == 0) fixedPartList.add(part)                if (part.getPoseType() == 1) dynamicPart.add(part)            }            //                    Log.e("测试", fixedPartList.size() + "");            // 判断是否全部满足固定部位标准            for (part in fixedPartList) {                val partIndex = part.getPoseIndex()                // 当前帧的角度                val nowFrameAngle: Int                // 自定义角度的情况                if (partIndex == -1) {                    nowFrameAngle = poseAngleDetector.getAnyAngleBy3Point(part.getThreePointIndex())                } else {                    nowFrameAngle = poseAngleDetector.getPoseAngleFromPartIndex(partIndex)                }                if (!(nowFrameAngle >= part.getFixedRange()[0] && nowFrameAngle <= part.getFixedRange()[1])) {                    addWarnPart(partIndex)                }                if (partIndex != -1) {                    if (nowFrameAngle < part.getFixedRange()[0]) {                        poseTips += "，" + getPartName(partIndex) + "角度要大一点"                    }                    if (nowFrameAngle > part.getFixedRange()[1]) {                        poseTips += "，" + getPartName(partIndex) + "角度小一点"                    }                }            }            if (confidence != 1f) {                CameraXLivePreviewActivity.confidenceNotOne = true                addWarnPartFlag = true            }            // 判断是否全部满足动态部位第一个标准            // 能够分清动作是up or down 并且置信度等于 1            if (maxConfidenceClass != null && confidence == 1f) {                for (part in dynamicPart) {                    val partIndex = part.getPoseIndex()                    // 当前帧的角度                    val nowFrameAngle: Int                    // 自定义角度的情况                    if (partIndex == -1) {                        nowFrameAngle =                            poseAngleDetector.getAnyAngleBy3Point(part.getThreePointIndex())                    } else {                        nowFrameAngle = poseAngleDetector.getPoseAngleFromPartIndex(partIndex)                    }                    if (maxConfidenceClass!!.contains("down")) {                        // 判断当前的角度是否满足第二个标准                        if (!(nowFrameAngle >= part.getSecondStandardRange()[0] && nowFrameAngle <= part.getSecondStandardRange()[1]) && addWarnPartFlag) {                            addWarnPart(partIndex)                            Logger.e("当前置信度" + confidence)                        }                        if (nowFrameAngle < part.getSecondStandardRange()[0]) {                            poseTips += "，" + getPartName(partIndex) + "角度要大一点"                        }                        if (nowFrameAngle > part.getSecondStandardRange()[1]) {                            poseTips += "，" + getPartName(partIndex) + "角度小一点"                        }                        if (!addWarnPartFlag && nowFrameAngle < part.getSecondStandardRange()[0]) {                            addWarnPart(partIndex)                            Logger.e("当前置信度" + confidence)                        }                    }                    if (maxConfidenceClass!!.contains("up")) {                        // 判断当前的角度是否满足第一个标准                        if (!(nowFrameAngle >= part.getFirstStandardRange()[0] && nowFrameAngle <= part.getFirstStandardRange()[1]) && addWarnPartFlag) {                            addWarnPart(partIndex)                        }                        if (nowFrameAngle < part.getFirstStandardRange()[0]) {                            poseTips += "，" + getPartName(partIndex) + "角度要大一点"                        }                        if (nowFrameAngle > part.getFirstStandardRange()[1]) {                            poseTips += "，" + getPartName(partIndex) + "角度小一点"                        }                    }                }                addWarnPartFlag = false            }        }        Log.i("pos_result", Gson().toJson(result))        return result    }    /**     * 获取部位名称     *     * @param index 身体部位索引     * @return 身体部位名称     */    fun getPartName(index: Int): String {        val partNames = arrayOf<String>(            "",            "右手腕",            "右胳膊肘",            "右手臂与肩膀",            "左手臂与肩膀",            "左胳膊肘",            "左手腕",            "右腿与身体",            "左腿与身体",            "右膝盖",            "左膝盖",            "右脚腕",            "左脚腕"        )        return partNames[index]    }    companion object {        private const val TAG = "PoseClassifierProcessor"        //    private static final String POSE_SAMPLES_FILE = "pose/squat_csvs_out_basic.csv";        //    private static final String POSE_SAMPLES_FILE = "pose/juanfumoxi.csv";        // // TODO: 2022/3/8 可以把这个设为静态成员变量，不同动作切换不同的文件生成不同的分类器        private var POSE_SAMPLES_FILE = "pose/lsttlsj.csv"        //    private static final String POSE_SAMPLES_FILE = "pose/tunqiao.csv";        @Volatile        var maxConfidenceClass: String? = null        // Specify classes for which we want rep counting.        // These are the labels in the given {@code POSE_SAMPLES_FILE}. You can set your own class labels        // for your pose samples.        // 置信度        @Volatile        var confidence: Float = 0f        private const val PUSHUPS_CLASS = "lsttlsj_down"        //        private const val SQUATS_CLASS = "squats_down"        private val POSE_CLASSES = arrayOf<String?>(            PUSHUPS_CLASS        )        @Volatile        var poseTips: String? = null    }}